const transitionRun = `-- name: TransitionRun :one
UPDATE runs SET
    status = $1,
    status_reason = $2,
    failure_class = coalesce($3, failure_class),
    started_at = CASE
        WHEN $1::run_status = 'running' AND started_at IS NULL THEN now()
        ELSE started_at END,
    finished_at = CASE
        WHEN $1::run_status IN ('succeeded', 'failed', 'cancelled', 'timed_out') THEN now()
        ELSE finished_at END
WHERE id = $4 AND workspace_id = $5 AND status = $6
RETURNING id, workspace_id, skill_version_id, test_case_snapshot_id, status, status_reason, provider, runtime_snapshot, policy_snapshot, cleanup_status, cleanup_at, created_at, started_at, finished_at, cancel_requested_at, failure_class, supervision_checked_at, cleanup_attempted_at, artifacts_truncated
`

type TransitionRunParams struct {
	ToStatus     RunStatus
	Reason       *string
	FailureClass *string
	RunID        pgtype.UUID
	WorkspaceID  pgtype.UUID
	FromStatus   RunStatus
}

func (q *Queries) TransitionRun(ctx context.Context, arg TransitionRunParams) (Run, error) {
	row := q.db.QueryRow(ctx, transitionRun,
		arg.ToStatus,
		arg.Reason,
		arg.FailureClass,
		arg.RunID,
		arg.WorkspaceID,
		arg.FromStatus,
	)
	var i Run
	err := row.Scan(
		&i.ID,
		&i.WorkspaceID,
		&i.SkillVersionID,
		&i.TestCaseSnapshotID,
		&i.Status,
		&i.StatusReason,
		&i.Provider,
		&i.RuntimeSnapshot,
		&i.PolicySnapshot,
		&i.CleanupStatus,
		&i.CleanupAt,
		&i.CreatedAt,
		&i.StartedAt,
		&i.FinishedAt,
		&i.CancelRequestedAt,
		&i.FailureClass,
		&i.SupervisionCheckedAt,
		&i.CleanupAttemptedAt,
		&i.ArtifactsTruncated,
	)
	return i, err
}

const unlockRunArtifactObjectSession = `-- name: UnlockRunArtifactObjectSession :one
SELECT pg_advisory_unlock(hashtextextended($1::text, 0))
`

func (q *Queries) UnlockRunArtifactObjectSession(ctx context.Context, lockKey string) (bool, error) {
	row := q.db.QueryRow(ctx, unlockRunArtifactObjectSession, lockKey)
	var pg_advisory_unlock bool
	err := row.Scan(&pg_advisory_unlock)
	return pg_advisory_unlock, err
}
